def ask(p,tag,stem,opts,why,*,kind='conceptual',difficulty='easy',ass=(),steps=(),formulas=(),cites=None,conflict=None,primary=(),correct=(0,),notes=None):
 cid=f'{B}-C-{tag}';c=CM[cid];qid=f'{B}-P{p}-Q{1+sum(q["id"].startswith(f"{B}-P{p}-Q")for q in Q):02}'
 assert len(opts)==len(why) and len(set(opts))==len(opts)
 if cites is None:cites=[(p,'statement','Main definition and explanatory bullets')]
 cc=[]
 for page,ck,loc in cites:
  cc.append(dict(slideId=f'lectures-p{page}',sourceId='lectures',sourceSha256=SHA,physicalPage=page,kind=ck,locator=f'Printed slide {page-1439}: '+loc,evidenceText=T[page],role='conflict'if conflict and page==conflict['physicalPage']else'premise'if kind in ['numerical','synthesis','algorithm_trace']else'explicit',region=None))
 oo=[dict(id=f'o{i+1}',text=x)for i,x in enumerate(opts)];shift=int(hashlib.sha256(qid.encode()).hexdigest()[:4],16)%len(oo);oo=oo[shift:]+oo[:shift]
 just=' '.join(why[i]for i in correct)
 q=dict(id=qid,version=1,status='draft',authorId=A,stem=stem,selectionMode='multi'if len(correct)>1 else'single',type=kind,difficulty=difficulty,cognitiveSkill='numerical'if kind=='numerical'else'algorithm'if kind=='algorithm_trace'else'synthesis'if kind=='synthesis'else'application'if kind in ['scenario','diagram']else'recall'if kind=='definition'else'conceptual',week=10,lectureId='L46',topic=TITLE,subtopic=c['title'],tags=['nlp',tag],conceptIds=[cid],assumptions=list(ass),options=oo,correctOptionIds=[f'o{i+1}'for i in correct],citations=cc,solution=dict(justification=just,optionExplanations={f'o{i+1}':('Correct. 'if i in correct else'Incorrect. ')+w for i,w in enumerate(why)},steps=list(steps),formulas=list(formulas),simpleExplanation=just,memoryAid=None,misconceptions=[why[i]for i in range(len(opts))if i not in correct],examTraps=[],prerequisiteConceptIds=[]),origin='generated',reviewIds=[])
 if len(opts)<4:q['optionCountRationale']='These alternatives exhaust the distinct credible interpretations tested; no filler option is added.'
 if conflict:q['conflictResolution']=dict(status='explicit-qualification-pending-independent-review',questionVersion=1,sourceId='lectures',sourceSha256=SHA,physicalPage=conflict['physicalPage'],sourceClaim=conflict['finding'],basis=conflict['handling'],method=conflict['method'],scope='This question version only; independent review required.',sourceIssueId=conflict['id'])
 if primary:q['primaryEvidence']=list(primary)
 if notes:q['notes']=notes
 Q.append(q);c['questionIds'].append(qid);c['status']='drafted';return q

def save():
 base.update(questions=Q,concepts=C,coverageNote=f'Author checkpoint: {len(Q)} drafts, all 36 pages actually inspected; independent review not yet performed.')
 write(f'data/question-batches/{B}.json',base);write(f'audits/source-disputes-{B}.json',ISS)
 print('Saved',len(Q),'drafts',flush=True)

