ask(1453,'one-hot-code','For words=[["pick"],["red"],["ball"],["near"],["chair"]], what are the source encoder’s column order and encoded row for red?', ['ball, chair, near, pick, red; [0,0,0,0,1]','pick, red, ball, near, chair; [0,1,0,0,0]','ball, chair, near, pick, red; [0,1,0,0,0]','ball, chair, near, pick, red; [1,1,1,1,1]'],['Automatically learned string categories are ordered alphabetically, so red occupies the final feature.','This uses input occurrence order as the feature order, unlike the shown fitted encoder.','The 1 here would identify chair, not red.','Only the matching category is active for a one-hot row.'],kind='algorithm_trace',steps=['Fit one categorical feature to five distinct strings.','Read categories in sorted order: ball, chair, near, pick, red.','Place red’s single 1 at zero-based feature index 4.'],formulas=[OHF],cites=[(1453,'code','Five nested input rows and fit_transform'),(1453,'table','x0_* column labels and red row')],primary=[OHAPI,nb(15)])
ask(1453,'one-hot-code','The output table marks red on row index 1. Does that make its active feature column index 1?', ['No; row index 1 identifies the second sample, while red’s feature column is index 4','Yes; input row and output feature indices must be equal for every encoder','No; every one-hot row uses feature column 0 because there is one input feature','Yes; the active column follows the number of earlier token occurrences'],['Rows retain sample order while columns index learned categories; these are different axes.','The matrix need not be an identity matrix in input order.','One categorical input feature expands into multiple category columns.','Occurrence order does not determine the learned alphabetical category index.'],kind='diagram',cites=[(1453,'table','Red annotations around row index 1 and its one-hot row')])
