ask(1458,'embeddings','For two nonzero vectors in the same space, which change leaves cosine similarity unchanged?', ['Multiplying one vector by a positive scalar','Adding the same nonzero constant to every coordinate of one vector','Replacing one vector by its negative while retaining the similarity sign','Replacing one vector by the zero vector'],['A positive scale multiplies both the dot product and that vector’s norm by the same factor.','Translation generally changes direction and therefore cosine.','Negating one vector reverses the cosine sign unless it was zero.','The denominator becomes zero, so the printed formula is undefined.'],kind='conceptual',steps=['Let A′=kA with k>0.','The numerator becomes k(A·B), and the denominator becomes k||A||||B||.','Cancel k.'],formulas=[COSF,fm('cos(kA,B)=cos(A,B), k>0',{'A,B':'Nonzero embedding vectors','k':'Positive rescaling factor'},{'A,B,k':'dimensionless'},['Common embedding space; no zero vector.'])],cites=[(1458,'equation','Norm-normalized dot product')])
