# Author quality pass before any independent exposure: technical, parallel alternatives.
QM={q['id']:q for q in Q}
def refine(suffix,opts,reasons,stem=None):
 q=QM[B+'-'+suffix];assert len(opts)==len(reasons)
 old_order=[o['id']for o in q['options']];new={f'o{i+1}':t for i,t in enumerate(opts)}
 q['options']=[{'id':k,'text':new[k]}for k in old_order if k in new]
 q['solution']['optionExplanations']={f'o{i+1}':('Correct. 'if i==0 else'Incorrect. ')+r for i,r in enumerate(reasons)}
 q['solution']['justification']=q['solution']['simpleExplanation']=reasons[0];q['solution']['misconceptions']=reasons[1:]
 if stem:q['stem']=stem
 if len(opts)<4:q['optionCountRationale']='Three distinct technical alternatives are sufficient for this narrow distinction; a fourth would be filler.'
